import {shiftDate,validDate} from './core.js';
export function monday(date){const weekday=new Date(date+'T12:00:00Z').getUTCDay();return shiftDate(date,-((weekday+6)%7))}
export function bounds(date,mode){if(!validDate(date))throw Error('Invalid date');if(mode==='day')return {start:date,end:date};if(mode==='week'){const start=monday(date);return {start,end:shiftDate(start,6)}}const start=date.slice(0,7)+'-01',d=new Date(start+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(0);return {start,end:d.toISOString().slice(0,10)}}
export function navigate(date,mode,direction){if(mode==='day'||mode==='week')return shiftDate(date,(mode==='day'?1:7)*direction);const d=new Date(date.slice(0,7)+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+direction);return d.toISOString().slice(0,10)}
export function groupTransactions(items,date,mode){const range=bounds(date,mode),visible=items.filter(t=>t.date>=range.start&&t.date<=range.end);const groups=[];if(mode==='day')groups.push({id:date,start:date,end:date,items:visible});else if(mode==='week'){for(let i=0;i<7;i++){const day=shiftDate(range.start,i);groups.push({id:day,start:day,end:day,items:visible.filter(t=>t.date===day)})}}else{for(let start=monday(range.start);start<=range.end;start=shiftDate(start,7)){const a=start<range.start?range.start:start,b=shiftDate(start,6)>range.end?range.end:shiftDate(start,6);groups.push({id:start,start:a,end:b,items:visible.filter(t=>t.date>=a&&t.date<=b)})}}return {range,visible,groups}}
export function sum(items){return items.reduce((n,t)=>n+t.amountCents,0)}
